  93	func (m *chatModel) handleSubmit() (tea.Model, tea.Cmd) {
  94		m.syncInputPlaceholders()
  95		input := strings.TrimSpace(string(m.input))
  96		if input == "" {
  97			return *m, nil
  98		}
  99		_, _, hasSlashCommand := slashCommandInvocation(input)
 100		if (m.running || m.compacting) && !hasSlashCommand {
 101			m.status = "wait for current response"
 102			return *m, nil
 103		}
 104	
 105		attachments := cloneInputAttachments(m.inputAttachments)
 106		pastedTexts := cloneInputPastedTexts(m.inputPastedTexts)
 107		m.input = nil
 108		m.inputCursor = 0
 109		m.inputCursorSet = false
 110		m.inputAttachments = attachments
 111		m.inputPastedTexts = pastedTexts
 112		m.complete = 0
