 379	// skillSlashInvocation parses "/<skill-name>" or "/<skill-name> <prompt>".
 380	// It returns the skill name, any trailing prompt, and ok when the first token is
 381	// a catalog skill. Built-in slash commands take precedence over same-named
 382	// skills, so they are never claimed here.
 383	func (m *chatModel) skillSlashInvocation(input string) (name, prompt string, ok bool) {
 384		input = strings.TrimSpace(input)
 385		if !strings.HasPrefix(input, "/") {
 386			return "", "", false
 387		}
 388		token, args, _ := strings.Cut(input, " ")
 389		name = strings.TrimPrefix(token, "/")
 390		if name == "" {
 391			return "", "", false
 392		}
 393		if _, _, known := slashCommandInvocation(input); known {
 394			return "", "", false
 395		}
 396		if _, err := m.opts.Skills.Load(name); err != nil {
 397			return "", "", false
 398		}
 399		return name, strings.TrimSpace(args), true
 400	}
