1394	func oq3Summarise(results []oq3ScenarioResult, mode, source, ledgerSHA string) oq3Summary {
1395		s := oq3Summary{Mode: mode, Source: source, CategoryCounts: map[string]int{}, PerFamily: map[string]any{}, PerTrial: map[string]any{},
1396			OperationVerdicts: map[string]int{}, RefusalVerdicts: map[string]int{}, AuxiliaryChecks: map[string]int{}, LedgerSHA256: ledgerSHA, Valid: true}
1397		family := map[string]string{}
1398		type tally struct{ Observed, Bad, Missing, Correct int }
1399		trialT := map[string]*tally{}
1400		for _, r := range results {
1401			s.ScenariosRun = append(s.ScenariosRun, r.Scenario.ID)
1402			for _, tr := range r.Scenario.Trials {
1403				family[tr.ID] = tr.Family
1404				trialT[tr.ID] = &tally{}
1405				s.Trials++
1406			}
1407			for _, d := range r.Deliveries {
1408				t := trialT[d.Trial]
1409				switch d.Status {
1410				case "correct":
1411					s.ObservedDeliveries++
1412					t.Observed++
1413					t.Correct++
1414				case "bad":
1415					s.ObservedDeliveries++
1416					s.BadObserved++
1417					t.Observed++
1418					t.Bad++
1419				case "missing":
1420					s.MissingRequired++
1421					t.Missing++
1422				case "unexpected":
1423					s.ObservedDeliveries++
1424					s.Unexpected++
1425					s.BadObserved++
1426					t.Observed++
1427					t.Bad++
1428				case "refused-as-required":
1429					s.RefusalsHeld++
1430				}
1431				for _, c := range d.Verdict.Categories {
1432					s.CategoryCounts[c]++
1433				}
1434			}
1435			for _, a := range r.Auxiliary {
1436				s.AuxiliaryChecks[a.Kind+":"+a.Status]++
1437				if a.Status != "correct" {
1438					s.AuxiliaryBad++
1439					s.AuxiliaryBadList = append(s.AuxiliaryBadList, fmt.Sprintf("%s %s %v", a.Label, a.Kind, a.Verdict.Categories))
1440				}
1441			}
1442			s.NotMeasured = append(s.NotMeasured, r.NotMeasured...)
1443			for _, e := range r.Events {
1444				switch e.Class {
1445				case "operation":
1446					s.OperationVerdicts[e.Op+":"+e.Verdict]++
1447				case "required-refusal":
1448					s.RefusalVerdicts[e.Op+":"+e.Verdict]++
1449				}
1450			}
1451			if len(r.Invalid) > 0 {
1452				s.Valid = false
1453				s.Invalid = append(s.Invalid, r.Invalid...)
1454			}
1455		}
1456		fam := map[string]*tally{}
1457		for id, t := range trialT {
1458			f := family[id]
1459			if fam[f] == nil {
1460				fam[f] = &tally{}
1461			}
1462			fam[f].Observed += t.Observed
1463			fam[f].Bad += t.Bad
1464			fam[f].Missing += t.Missing
1465			fam[f].Correct += t.Correct
1466			s.PerTrial[id] = map[string]any{"family": f, "observed": t.Observed, "correct": t.Correct, "bad": t.Bad, "missing": t.Missing}
1467		}
1468		famTrials := map[string]int{}
1469		for _, f := range family {
1470			famTrials[f]++
1471		}
1472		for f, t := range fam {
1473			s.PerFamily[f] = map[string]any{"trials": famTrials[f], "observed": t.Observed, "correct": t.Correct, "bad": t.Bad, "missing": t.Missing,
1474				"failure_number": oq3Ratio(t.Bad+t.Missing, famTrials[f])}
1475		}
1476		s.FailureNumerator = s.BadObserved + s.MissingRequired
1477		s.FailureNumber = oq3Ratio(s.FailureNumerator, s.Trials)
1478		return s
1479	}
