196	func (m chatModel) previewChatRequest(opts coreagent.RunOptions, messages []api.Message) api.ChatRequest {
197		requestMessages := slices.Clone(messages)
198		if strings.TrimSpace(opts.SystemPrompt) != "" {
199			withSystem := make([]api.Message, 0, len(requestMessages)+1)
200			withSystem = append(withSystem, api.Message{Role: "system", Content: opts.SystemPrompt})
201			requestMessages = append(withSystem, requestMessages...)
202		}
203	
204		format := opts.Format
205		if format == "json" {
206			format = `"` + format + `"`
207		}
208	
209		req := api.ChatRequest{
210			Model:    opts.Model,
211			Messages: requestMessages,
212			Format:   json.RawMessage(format),
213			Options:  opts.Options,
214			Think:    opts.Think,
215		}
216		if opts.KeepAlive != nil {
217			req.KeepAlive = opts.KeepAlive
218		}
219		if m.opts.Tools != nil && !m.opts.ToolsDisabled {
220			req.Tools = m.opts.Tools.Tools()
221		}
222		return req

