    16	type oq3Step struct {
    17		Op     string            `json:"op"`
    18		Class  string            `json:"class"`
    19		Trial  string            `json:"trial,omitempty"`
    20		Conv   string            `json:"conv,omitempty"`
    21		Prompt string            `json:"prompt,omitempty"`
    22		Expect []oq3Expect       `json:"expect,omitempty"`
    23		Want   map[string]string `json:"want,omitempty"`
    24		Args   map[string]string `json:"args,omitempty"`
    25		// Summarisers is the number of compaction summariser requests this step must cause.
    26		Summarisers int `json:"summarisers,omitempty"`
    27	}
